pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playCalls) public {
        // Bound the number of calls to avoid infinite loop but keep it wide enough to trigger the bug
        playCalls = bound(playCalls, 0, 20);

        // Play the lotto „playCalls“ times as a standard player
        address player = makeAddr("player");
        vm.deal(player, playCalls * 10 ether); // enough for many tickets
        vm.startPrank(player);
        for (uint256 i = 0; i < playCalls; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();

        // The invariant: pot == (address(c).balance - totalFeesAlreadyTransferred)
        // The bank is paid 1 wei on every win; the probability of win is ~50%.
        // So totalFeesExpected	≈ floor(playCalls/2)*1 (but we don’t compute it exactly).
        // Instead, we observe that the contract’s ether balance &
        // the pot value MUST satisfy: the pot can never be larger than the
        // actual ether held by C, because any pot increase only comes from
        // deposits (= 10), and any deduction happens only on actual transfer.
        // In the bug, pot increases by msg.value+1, so after enough plays
        // pot > address(c).balance is possible.
        assertTrue(c.pot() <= address(c).balance, "invariant: pot <= ETH balance");
    }
}

