contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 plays, uint256 seed) public {
        // plays in [1, 50] keeps runtime reasonable while allowing many wins
        plays = bound(plays, 1, 50);
        vm.warp(1);
        vm.roll(1);
        uint256 totalPaid = 0;
        uint256 feesPaid = 0;
        address player = address(uint160(uint256(keccak256(abi.encode(seed)))));
        for (uint256 i = 0; i < plays; i++) {
            vm.roll(block.number + 1);
            vm.warp(block.timestamp + 1);
            vm.deal(player, 10 ether);
            vm.prank(player);
            bool win = (uint256(keccak256(abi.encode(i, seed))) % 2 == 0);
            if (win) {
                totalPaid += 10;
                feesPaid += 1;
            } else {
                totalPaid += 10;
            }
            c.play{value: 10}();
        }
        // invariant: pot + bank balance == totalPaid - feesPaid
        assertEq(c.pot() + address(c.bank()).balance + address(c).balance, totalPaid - feesPaid);
    }
}

