pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 seed1, uint8 seed2, uint8 senderSeed) public {
        // Bound to keep hashes in range that still triggers both loss and win
        // We need to ensure the first call is a loss (random=1) and second is a win (random=0)
        // The fuzzer will find appropriate seeds that satisfy this.

        address sender = address(uint160(uint(keccak256(abi.encode(senderSeed)))));
        vm.deal(sender, 20 ether);

        // First call: loss scenario (random = 1)
        vm.roll(100);
        vm.warp(1000);
        // We need to ensure random=1 for first call, random=0 for second call
        // We'll rely on the fuzzer to find seeds that produce these outcomes
        vm.prank(sender);
        c.play{value: 10}();

        // Second call: win scenario (random = 0)
        vm.roll(200);
        vm.warp(2000);
        vm.prank(sender);
        c.play{value: 10}();

        // After a win, pot should always be 0 in reference, but buggy can leave pot non-zero
        assertTrue(c.pot() == 0);
    }
}

