        n = uint8(bound(n, 1, 3));
        vm.assume(sender != address(0));
        vm.assume(sender != address(c));
        vm.deal(sender, 100 ether);

        uint expectedPot = 0;
        for (uint i = 0; i < n; i++) {
            uint random;
            if (i == 0) random = seed1 % 2;
            else if (i == 1) random = seed2 % 2;
            else random = seed3 % 2;

            expectedPot += 10;
            vm.prank(sender);
            c.play{value: 10}();
            if (random == 0) {
