pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 numCalls) public {
        vm.assume(numCalls > 0 && numCalls <= 10);
        uint256 totalPaid = 0;
        uint256 wins = 0;
        for (uint256 i = 0; i < numCalls; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10 ether);
            uint256 blockTimestamp = block.timestamp + i;
            uint256 blockDifficulty = block.difficulty + i;
            uint256 random = uint256(keccak256(abi.encodePacked(blockTimestamp, blockDifficulty, player))) % 2;
            vm.warp(blockTimestamp);
            vm.roll(blockDifficulty);
            vm.prank(player);
            c.play{value: 10}();
            totalPaid += 10;
            if (random == 0) {
                wins += 1;
            }
        }
        assertTrue(c.pot() == totalPaid - wins * 1);
    }
}
